import type { Candidate, Experience, IndexBreakdown, Qualification, Skill, Verification } from "./types";

/* Sample professional records. The marketplace total (102,480) lives in
   metrics.ts; these are the representative records the demo can open. All
   people and employers here are fictional. */

const V: Record<string, Verification> = { v: "verified", s: "self", p: "pending" };

const skills = (list: string[]): Skill[] => list.map(s => {
  const [name, level, v] = s.split("|");
  return { name, level: Number(level), verification: V[v] || "self" };
});
const quals = (list: string[]): Qualification[] => list.map(s => {
  const [name, issuer, year, v] = s.split("|");
  return { name, issuer, year: Number(year), verification: V[v] || "self" };
});
type ExpRow = [string, string, string, string, string, string, string, string[], string];
const exps = (rows: ExpRow[]): Experience[] => rows.map(r => ({
  role: r[0], orgPublic: r[1], org: r[2], location: r[3], from: r[4], to: r[5], summary: r[6], achievements: r[7], verification: V[r[8]] || "self",
}));

/** Splits an index across the five evidence areas so the parts always add up. */
export function splitIndex(index: number): IndexBreakdown {
  const experience = Math.round(index * 0.333);
  const skills = Math.round(index * 0.226);
  const leadership = Math.round(index * 0.19);
  const qualifications = Math.round(index * 0.13);
  return { experience, skills, leadership, qualifications, evidence: index - experience - skills - leadership - qualifications };
}

const TINTS = ["#9fb4ff", "#7fe0d2", "#e6c78a", "#c8b4f0", "#a8e0c0", "#f0b8c8", "#9fd6f0", "#f2c59a", "#b8d48a", "#d8c0a8"];

type Lite = {
  id: string; name: string; title: string; orgPublic: string; org: string; sector: string; location: string; region: string;
  years: number; cur: number; exp: [number, number]; mkt: [number, number]; idx: number;
  avail: Candidate["availability"]; notice: number; vis?: Candidate["visibility"]; team: number; summary: string;
  skills: string[]; transferable: string[]; quals: string[]; rows: ExpRow[]; achievements: string[];
  preferred: string[]; interests?: string[]; languages?: string[]; completeness: number; verified: number; status?: Candidate["status"];
};

let tintAt = 3;
function mk(c: Lite): Candidate {
  const [first, ...rest] = c.name.split(" ");
  const last = rest.join(" ");
  const initials = (first[0] + (last[0] || "")).toUpperCase();
  const slug = (first + "." + last).normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/[^a-z.]/g, "");
  return {
    id: c.id, name: c.name, initials, tint: TINTS[tintAt++ % TINTS.length], title: c.title,
    currentOrgPublic: c.orgPublic, currentOrg: c.org, sector: c.sector, industry: c.sector === "Retail" || c.sector === "Facilities" ? c.sector : "Hospitality",
    location: c.location, region: c.region, years: c.years, salaryCurrent: c.cur, salaryExpectation: c.exp, marketRange: c.mkt,
    recruitIndex: c.idx, breakdown: splitIndex(c.idx), availability: c.avail, noticeWeeks: c.notice, visibility: c.vis || "discoverable",
    teamSize: c.team, summary: c.summary, skills: skills(c.skills), transferable: c.transferable, qualifications: quals(c.quals),
    experience: exps(c.rows), achievements: c.achievements, preferredRoles: c.preferred, interests: c.interests || [],
    languages: c.languages || ["English"], volunteer: [], completeness: c.completeness, verifiedCredentials: c.verified,
    joined: "Member for 9 months", email: slug + "@mail.example", phone: "+353 8" + (c.idx % 7) + " " + (100 + c.idx % 800) + " " + (1000 + c.idx * 7 % 9000),
    status: c.status || "active",
  };
}

